-- create "content_publish_hooks" table
CREATE TABLE "content_publish_hooks" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "shop_id" bigint NOT NULL, "url_ciphertext" bytea NOT NULL, "host" character varying(253) NOT NULL, "url_hint" character varying(8) NOT NULL DEFAULT '', "signing_secret_ciphertext" bytea NOT NULL, "enabled" boolean NOT NULL DEFAULT true, "disabled_reason" character varying(30) NOT NULL DEFAULT '', "last_status" character varying(20) NOT NULL DEFAULT '', "last_http_status" bigint NOT NULL DEFAULT 0, "last_attempt_at" timestamptz NULL, "last_success_at" timestamptz NULL, "consecutive_failures" bigint NOT NULL DEFAULT 0, "cap_day" date NULL, "cap_count" bigint NOT NULL DEFAULT 0, "pending_since" timestamptz NULL, "pending_last_at" timestamptz NULL, "pending_event" character varying(30) NOT NULL DEFAULT '', "pending_key" character varying(63) NOT NULL DEFAULT '', "pending_rev" bigint NOT NULL DEFAULT 0, "pending_count" bigint NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "updated_by_user_id" bigint NULL, PRIMARY KEY ("id"));
-- create index "contentpublishhook_shop_id" to table: "content_publish_hooks"
CREATE UNIQUE INDEX "contentpublishhook_shop_id" ON "content_publish_hooks" ("shop_id");
-- hand-written: the flusher only looks at rows with pending state
CREATE INDEX "content_publish_hooks_pending_idx" ON "content_publish_hooks" ("pending_since") WHERE pending_since IS NOT NULL;
